package com.glassbox.chess.state; import com.glassbox.chess.command.MoveCommand; import com.glassbox.chess.game.ChessGame; import com.glassbox.engine.core.Game; import com.glassbox.engine.state.GamePhase; public class InProgressPhase implements GamePhase<MoveCommand>{public void handleMove(Game<MoveCommand> c,MoveCommand m)throws Exception{ChessGame g=(ChessGame)c;g.getHistory().execute(m);g.evaluateStateTransition();}public String getPhaseName(){return "In Progress";}public boolean isTerminal(){return false;}}
